{
  "status": "SUPPORTED",
  "task_summary": "Find a fastener, attach it to a target on the workbench using a tool, then leave the tool on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "compatible_component",
        "entity_kind": "OBJECT",
        "function": "The physical part to be fastened into place.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["bolt", "screw", "nut", "plug", "block"],
        "required_properties": ["fits_target", "suitable_for_fastening"]
      },
      {
        "id": "target_object",
        "entity_kind": "OBJECT",
        "function": "The object or assembly point receiving the fastener.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["assembly_part", "fixture", "base"],
        "required_properties": ["has_fastening_point", "receives_component"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to secure the component.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["wrench", "screwdriver", "pliers", "hammer"],
        "required_properties": ["can_drive_fastener", "manipulatable"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the task occurs and tool is left.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "bench"],
        "required_properties": ["flat_surface", "stable"]
      }
    ],
    "functional_relations": [
      {
        "id": "component_fits_target",
        "relation": "COMPATIBILITY",
        "participant_roles": ["compatible_component", "target_object"],
        "required": true
      },
      {
        "id": "tool_secures_connection",
        "relation": "OPERATION",
        "participant_roles": ["fastening_tool", "compatible_component", "target_object"],
        "required": true
      },
      {
        "id": "tool_left_on_bench",
        "relation": "POSITION",
        "participant_roles": ["fastening_tool", "workbench"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "fasten_component",
        "operation": "FASTEN",
        "participant_roles": ["compatible_component", "target_object", "fastening_tool"],
        "operation_count": 1
      },
      {
        "id": "place_tool",
        "operation": "PLACE",
        "participant_roles": ["fastening_tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "compatible_component": [],
      "target_object": [],
      "fastening_tool": [],
      "workbench": [
        {
          "label": "wooden_table",
          "visual_description": "Wooden workbench surface with drawers underneath."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "blue_cabinet",
        "visual_description": "Grey cabinet on the workbench.",
        "reason": "Closed storage structure that may contain compatible components or tools."
      },
      {
        "id": "under_table_drawers",
        "label": "under_table_drawers",
        "visual_description": "Two blue drawers under the workbench.",
        "reason": "Closed storage structures that may contain compatible components or tools."
      }
    ],
    "inspection_order": [
      "blue_cabinet",
      "under_table_drawers"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
